import{_ as o,C as i,o as t,c as d,a5 as a,b as n,w as r,a as c,E as l,a7 as h}from"./chunks/framework.QWVCgkrI.js";const _=JSON.parse('{"title":"Gitのreset — HEAD・index・作業ツリーはどう変わるのか","description":"","frontmatter":{"title":"Gitのreset — HEAD・index・作業ツリーはどう変わるのか","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"コミットを指定するresetを、先端、index、作業ファイルの三つに分けて読み、soft・mixed・hardとrevertの違いを比べる。","aliases":["Git reset","リセット","soft reset","mixed reset","hard reset","HEAD index 作業ツリー"],"verification":"Git公式資料と照合し、Windowsの独立リポジトリでsoft・mixed・hard実行後の参照とファイル内容を確認（2026-11-17）"}},"headers":[],"relativePath":"tools/git-reset.md","filePath":"tools/git-reset.md"}'),p={name:"tools/git-reset.md"};function E(m,e,A,g,f,x){const s=i("Mermaid");return t(),d("div",null,[e[1]||(e[1]=a('<h1 id="gitのreset-—-head・index・作業ツリーはどう変わるのか" tabindex="-1">Gitのreset — HEAD・index・作業ツリーはどう変わるのか <a class="header-anchor" href="#gitのreset-—-head・index・作業ツリーはどう変わるのか" aria-label="Permalink to &quot;Gitのreset — HEAD・index・作業ツリーはどう変わるのか&quot;">​</a></h1><p>敵のHPを20にしたコミットがあります。そのあとHPを30にしてステージし、作業ファイルはさらに40まで編集しました。ここで一つ前のコミットをreset先に選ぶと、soft・mixed・hardのいずれも、HP10のコミットが先端になります。次にコミットする予定の内容と、実際に編集中のファイルはモードによって変わります。<a href="https://git-scm.com/docs/git-reset#_description" target="_blank" rel="noreferrer">Git公式のresetマニュアル</a></p><h2 id="三つの状態のうち、何を揃えるか" tabindex="-1">三つの状態のうち、何を揃えるか <a class="header-anchor" href="#三つの状態のうち、何を揃えるか" aria-label="Permalink to &quot;三つの状態のうち、何を揃えるか&quot;">​</a></h2><p><code>HEAD</code> は現在のコミットを特定する参照です。ブランチ上では <code>HEAD</code> はブランチを指し、ブランチがコミットを指します。そのコミットのスナップショットが、差分を測る基準になります。indexは次のコミットに使うファイルの内容を持ち、作業ツリーにはいま開いて編集しているファイルがあります。<code>git add</code> のあとに再編集すれば、この三つに同じファイルの別々の版がある状態になります。<a href="/study/tools/git-objects.html">Gitの保存モデル</a> · <a href="/study/tools/git-staging-index.html">Gitのステージング</a></p><p>コミットAを指定するresetでは、モードによってAに合わせる範囲が広がります。図の矢印は更新される対象を示します。</p>',5)),(t(),n(h,null,{default:r(()=>[l(s,{id:"mermaid-15",class:"mermaid",graph:"---%0Aconfig%3A%0A%20%20flowchart%3A%0A%20%20%20%20nodeSpacing%3A%2012%0A%20%20%20%20rankSpacing%3A%2040%0A%20%20%20%20padding%3A%208%0A---%0Aflowchart%20TD%0A%20%20%20%20accTitle%3A%20reset%E3%81%AE3%E3%83%A2%E3%83%BC%E3%83%89%E3%81%8C%E6%8C%87%E5%AE%9A%E3%82%B3%E3%83%9F%E3%83%83%E3%83%88%E3%81%AB%E6%8F%83%E3%81%88%E3%82%8B%E5%AF%BE%E8%B1%A1%0A%20%20%20%20accDescr%3A%20%E3%81%A9%E3%81%AE%E3%83%A2%E3%83%BC%E3%83%89%E3%82%82HEAD%E3%81%8B%E3%82%89%E8%A6%8B%E3%81%88%E3%82%8B%E3%82%B3%E3%83%9F%E3%83%83%E3%83%88%E3%82%92A%E3%81%AB%E3%81%99%E3%82%8B%E3%80%82mixed%E3%81%A8hard%E3%81%AFindex%E3%82%82A%E3%81%AB%E6%8F%83%E3%81%88%E3%82%8B%E3%80%82hard%E3%81%AF%E4%BD%9C%E6%A5%AD%E3%83%84%E3%83%AA%E3%83%BC%E3%81%AE%E5%AF%BE%E8%B1%A1%E3%83%95%E3%82%A1%E3%82%A4%E3%83%AB%E3%82%82A%E3%81%AB%E6%8F%83%E3%81%88%E3%82%8B%E3%80%82%0A%20%20%20%20target%5B%22%E6%8C%87%E5%AE%9A%E3%82%B3%E3%83%9F%E3%83%83%E3%83%88%20A%22%5D%20--%3E%7C%E5%85%A8%E3%83%A2%E3%83%BC%E3%83%89%7C%20head%5B%22HEAD%22%5D%0A%20%20%20%20target%20--%3E%7Cmixed%20%2F%20hard%7C%20idx%5B%22index%22%5D%0A%20%20%20%20target%20--%3E%7Chard%7C%20work%5B%22%E4%BD%9C%E6%A5%AD%E3%83%84%E3%83%AA%E3%83%BC%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<ul><li><strong><code>--soft</code></strong> はブランチの先端をAに移します。indexと作業ファイルには、実行前の版が残ります。</li><li><strong><code>--mixed</code></strong> は先端を移し、indexをAの内容に揃えます。作業ファイルはそのままです。コミットを指定し、モードを省いた場合の既定です。</li><li><strong><code>--hard</code></strong> は先端とindexをAに揃え、作業ツリーにもAの追跡ファイルを書き出します。Aにない追跡ファイルは取り除かれます。書き出しを妨げるパスでは未追跡のファイルやディレクトリも失われる場合があります。別の検証例では、同じパスにあった未追跡の <code>enemy.txt</code> が上書きされ、無関係な未追跡ファイルの <code>notes.txt</code> は残りました。<a href="https://git-scm.com/docs/git-reset#_description" target="_blank" rel="noreferrer">Git公式のresetマニュアル</a></li></ul><p>図は <code>main</code> 上での例です。ブランチ上では <code>HEAD</code> が指すブランチの先端が更新されます。detached HEADでは <code>HEAD</code> がコミットを直接指すので、その直接の参照先が変わります。<a href="https://git-scm.com/docs/git-symbolic-ref#_description" target="_blank" rel="noreferrer">Git公式のsymbolic-refマニュアル</a> · <a href="https://git-scm.com/docs/git-update-ref#_description" target="_blank" rel="noreferrer">Git公式のupdate-refマニュアル</a></p><h2 id="hpの値と差分表示で比べる" tabindex="-1">HPの値と差分表示で比べる <a class="header-anchor" href="#hpの値と差分表示で比べる" aria-label="Permalink to &quot;HPの値と差分表示で比べる&quot;">​</a></h2><p>同じ初期状態を持つ3つの使い捨てリポジトリで、<code>enemy.txt</code> が <code>hp=10</code> のコミットAを指定しました。開始時の <code>main</code> は <code>hp=20</code> のBを指し、indexは <code>hp=30</code>、作業ツリーは <code>hp=40</code> でした。各行はそれぞれ別のリポジトリでの観察です。</p><table tabindex="0"><thead><tr><th>状態</th><th>HEADのHP</th><th>index / 作業ツリーのHP</th></tr></thead><tbody><tr><td>実行前</td><td>Bの20</td><td>30 / 40</td></tr><tr><td><code>--soft</code></td><td>Aの10</td><td>30 / 40</td></tr><tr><td><code>--mixed</code></td><td>Aの10</td><td>10 / 40</td></tr><tr><td><code>--hard</code></td><td>Aの10</td><td>10 / 10</td></tr></tbody></table><p><code>--soft</code> を実行したリポジトリで三つの値を読んだ出力です。<code>a57b882</code> がAで、実行前のBは <code>70e721f</code> でした。<code>git show &#39;:enemy.txt&#39;</code> はindexの版を読みます。<a href="https://git-scm.com/docs/gitrevisions" target="_blank" rel="noreferrer">Git公式のリビジョン指定</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; git rev-parse --short HEAD</span></span>
<span class="line"><span>a57b882</span></span>
<span class="line"><span>PS&gt; git show &#39;:enemy.txt&#39;</span></span>
<span class="line"><span>hp=30</span></span>
<span class="line"><span>PS&gt; Get-Content -LiteralPath enemy.txt</span></span>
<span class="line"><span>hp=40</span></span>
<span class="line"><span>PS&gt; git status --short</span></span>
<span class="line"><span>MM enemy.txt</span></span></code></pre></div><p>この例のように競合していない追跡ファイルでは、<code>git status --short</code> の1文字目はHEADとindex、2文字目はindexと作業ツリーの違いです。このファイルはsoftのあと <code>MM</code>、mixedのあと <code> M</code> になり、hardのあと表示から消えました。実行前も <code>MM</code> でしたが、softのあとにステージ済みとして表示される差分はHP20→30からHP10→30に変わります。indexの内容は30のままで、比較の基準がBからAに移った結果です。<a href="https://git-scm.com/docs/git-status#_short_format" target="_blank" rel="noreferrer">Git公式のstatusマニュアル</a> · <a href="/study/tools/git-staging-index.html">Gitのステージング</a></p><h2 id="パスを指定するresetと、revertの違い" tabindex="-1">パスを指定するresetと、revertの違い <a class="header-anchor" href="#パスを指定するresetと、revertの違い" aria-label="Permalink to &quot;パスを指定するresetと、revertの違い&quot;">​</a></h2><p><code>git reset -- enemy.txt</code> は、現在のHEADからそのファイルの内容をindexに写します。読み出し元のコミットも指定できます。別の検証例で <code>git reset a57b882 -- enemy.txt</code> を実行すると、indexはAの <code>hp=10</code> になり、HEADはB、作業ファイルは <code>hp=40</code> のままでした。パスを指定する形式では、指定したパスのindexだけを更新します。<a href="https://git-scm.com/docs/git-reset#_description" target="_blank" rel="noreferrer">Git公式のresetマニュアル</a></p><p>AからBへ進んだ履歴でコミット指定のresetをすると、ブランチの先端をAへ動かします。Bはそのブランチの先端からたどれなくなります。Bをrevertする場合は、Bの変更を打ち消す新しいコミットをBの先に追加します。取得済みの履歴と親がつながるため、共有ブランチでBの変更を取り消すときにも使えます。<a href="https://git-scm.com/docs/git#_reset_restore_and_revert" target="_blank" rel="noreferrer">Git公式のreset・restore・revertの解説</a> · <a href="/study/tools/git-revert.html">Gitのrevert</a></p><p>resetで先端が動いた記録は、reflogがあれば旧コミットを探す手掛かりになります。一方、作業ツリーにしかなかった <code>hp=40</code> は、先端の履歴を戻しても取り出せません。<a href="/study/tools/git-reflog.html">Gitのreflog</a></p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>softで先端だけ動かしたとき、ステージ済みの差分表示も変わる？</summary><p>変わります。indexはHP30のままですが、HEADがHP20のBからHP10のAに変わるため、HEADとindexを比較した差分が変わります。</p></details><details class="details custom-block"><summary>mixedのあと、作業ファイルのHP40はどこに残る？</summary><p>作業ツリーに残ります。HEADとindexはAのHP10に揃うため、HP40は未ステージの編集として表示されます。</p></details><details class="details custom-block"><summary>Bの変更をあとから打ち消した記録を履歴に残すのはどちら？</summary><p>revertです。変更を打ち消す新しいコミットを作るので、元のBも親をたどって見つかります。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月17日に、WindowsのGit 2.39.2.windows.1とSHA-1の使い捨てリポジトリを使いました。<code>main</code> にいる状態で、1つの追跡ファイルにステージ済みと未ステージの編集を作り、各モードの参照先・index・作業ファイルと差分表示を確認しました。パス指定と未追跡ファイルの上書きは、それぞれ別のリポジトリで検証しました。detached HEAD、進行中のmerge、サブモジュール、スパースチェックアウトは実行していません。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/tools/git-staging-index.html">Gitのステージング</a> — HEAD、index、作業ツリーの比較対象を確認する。</li><li><a href="/study/tools/git-objects.html">Gitの保存モデル</a> — 参照とスナップショットの関係を読む。</li><li><a href="/study/tools/git-revert.html">Gitのrevert</a> — 親を残したまま、変更を打ち消す新しいコミットを作る仕組みを読む。</li><li><a href="/study/tools/git-reflog.html">Gitのreflog</a> — 先端が以前指していたコミットの探し方と限界を確認する。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://git-scm.com/docs/git-reset#_description" target="_blank" rel="noreferrer">Git公式 — git-reset</a></li><li><a href="https://git-scm.com/docs/git-status#_short_format" target="_blank" rel="noreferrer">Git公式 — git-statusのshort形式</a></li><li><a href="https://git-scm.com/docs/git#_reset_restore_and_revert" target="_blank" rel="noreferrer">Git公式 — Reset, restore and revert</a></li><li><a href="https://git-scm.com/book/en/v2/Git-Tools-Reset-Demystified" target="_blank" rel="noreferrer">Pro Git — Reset Demystified</a></li></ul>`,22))])}const b=o(p,[["render",E]]);export{_ as __pageData,b as default};
